import { isSameParameter } from './is-same-parameter.util.js';
export function getClassParameters(metakey, metatype) {
    const parameters = Reflect.getMetadata(metakey, metatype) ?? [];
    if (parameters.length === 0) {
        return parameters;
    }
    const base = Object.getPrototypeOf(metatype);
    const inherited = Reflect.getMetadata(metakey, base) ?? [];
    const own = parameters.filter((param) => !inherited.includes(param));
    return [
        ...getClassParameters(metakey, base).filter((param) => !own.some((ownParam) => isSameParameter(ownParam, param))),
        ...own
    ];
}
